import { test } from "@e2e/fixtures";
import * as ui from "@e2e/ui-actions";

test.describe("Canvas controls", () => {
  test.use({
    inspectorOptions: {
      inspectMode: true,
    },
  });

  test("Fit, zoom in/out, and zoom to 100% controls adjust canvas viewport", async ({
    inspectorPage,
  }) => {
    await test.step("Fit to canvas shows the full flow graph", async () => {
      await ui.inspectorCanvas.actions(inspectorPage).zoomIn();
      await ui.inspectorCanvas.actions(inspectorPage).fitToCanvas();
      await ui.inspectorCanvas.assertions(inspectorPage).canvasWithNodesIsVisible();
    });

    await test.step("Zoom in and out change the zoom percentage", async () => {
      const initial =
        (await ui.inspectorCanvas.getLocators(inspectorPage).zoomTo100Button.textContent()) ??
        "100%";
      await ui.inspectorCanvas.actions(inspectorPage).zoomIn();
      await ui.inspectorCanvas.assertions(inspectorPage).zoomPercentageChangedFrom(initial);
      const afterZoomIn =
        (await ui.inspectorCanvas.getLocators(inspectorPage).zoomTo100Button.textContent()) ?? "";
      await ui.inspectorCanvas.actions(inspectorPage).zoomOut();
      await ui.inspectorCanvas.assertions(inspectorPage).zoomPercentageChangedFrom(afterZoomIn);
    });

    await test.step("Zoom to 100% resets zoom percentage", async () => {
      await ui.inspectorCanvas.actions(inspectorPage).zoomIn();
      await ui.inspectorCanvas.actions(inspectorPage).zoomTo100();
      await ui.inspectorCanvas.assertions(inspectorPage).zoomPercentageIs("100%");
    });
  });
});
